public TreeNode<T> rotateRight(TreeNode<T> node) {
        // store the left child of the node
        TreeNode<T> leftChild = node.leftChild;

        // move the left child to the right of the old parent
        node.leftChild = leftChild.rightChild;

        // set the right child of the new left child to the old parent
        leftChild.rightChild = node;

        // rebalance
        if (node.balanceFactor == 1) {
            // the node was balanced or had its balance on the left
            leftChild.balanceFactor = 0;
            node.balanceFactor = -1;
        } else {
            // the node had its balance on the right
            leftChild.balanceFactor = node.balanceFactor = 0;
        }

        // return the new parent
        return leftChild;
    }

