public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 100000000) {
        throw new IllegalArgumentException("Invalid timeBucket, must be a date in the YYYYMMDD format");
    }
    if (dayStep < 1 || dayStep > 31) {
        throw new IllegalArgumentException("Invalid dayStep, must be between 1 and 31");
    }
    String timeBucketStr = Long.toString(timeBucket);
    int year = Integer.parseInt(timeBucketStr.substring(0, 4));
    int month = Integer.parseInt(timeBucketStr.substring(4, 6));
    int day = Integer.parseInt(timeBucketStr.substring(6, 8));
    day = (day - 1) / dayStep * dayStep + 1;
    return Long.parseLong(String.format("%04d%02d%02d", year, month, day));
}

