        Calendar calendar = Calendar.getInstance();
        calendar.setTime(date);
        int dayOfWeek = calendar.get(Calendar.DAY_OF_WEEK);

        // Calculate the number of days to add to the time bucket to align it with the previous day step
        int offset = (dayStep - dayOfWeek + 7) % 7;

        // Add the offset to the time bucket to re-format it
        date.setTime(timeBucket + offset);

        // Return the re-formatted time bucket
        return date.getTime();
    }
}

