 * Split a box along the x axis into two equal boxes.
 * @param box the box to split
 * @return a pair with the two resulting boxes
 */
public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) throws IllegalArgumentException {
    if (box.isEmpty()) {
        throw new IllegalArgumentException("Cannot split an empty box.");
    }
    double xCenter = box.getX() + box.getWidth() / 2;
    Box2D box1 = new Box2D(box.getX(), box.getY(), xCenter - box.getX(), box.getHeight());
    Box2D box2 = new Box2D(xCenter, box.getY(), box.getX() + box.getWidth() - xCenter, box.getHeight());
    return new Pair<>(box1, box2);
}

