 */
public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }
    double xCenter = box.getCenterX();
    double yCenter = box.getCenterY();
    double width = box.getWidth() / 2.0;
    double height = box.getHeight() / 2.0;
    double xMin = xCenter - width / 2.0;
    double xMax = xCenter + width / 2.0;
    double yMin = yCenter - height / 2.0;
    double yMax = yCenter + height / 2.0;
    return new Pair<Box2D,Box2D>(new Box2D(xMin, yMin, width, height), new Box2D(xMax, yMax, width, height));
}

