    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split(",");
            if (parts.length != 4) {
                throw new IOException("Invalid thread snapshot format");
            }
            long threadId = Long.parseLong(parts[0]);
            long startTime = Long.parseLong(parts[1]);
            long endTime = Long.parseLong(parts[2]);
            long cpuTime = Long.parseLong(parts[3]);
            ThreadSnapshot snapshot = new ThreadSnapshot(threadId, startTime, endTime, cpuTime);
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timeRange.contains(startTime) || timeRange.contains(endTime)) {
                    snapshots.add(snapshot);
                    break;
                }
            }
        }
    }
    return snapshots;
